/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,
  // API paths are passed through to the USAspending API exactly as written, with or without a trailing slash.
  skipTrailingSlashRedirect: true,
};
export default nextConfig;

import fs from 'node:fs';
import path from 'node:path';

export function content(name: string) {
  return fs.readFileSync(path.join(process.cwd(), 'content', `${name}.md`), 'utf8');
}

import raw from './docs.json';

export type Field = {
  name?: string;
  type: string;
  required?: boolean;
  nullable?: boolean;
  description?: string;
  default?: unknown;
  example?: unknown;
  enum?: { value: unknown; description?: string }[];
  valueType?: string;
  items?: Field;
  fields?: Field[];
  options?: { fields: Field[] }[];
  ref?: string;
  refDescription?: string;
  in?: 'path' | 'query';
};

export type Endpoint = {
  id: string;
  method: string;
  path: string;
  title: string;
  status: 'stable' | 'in-development' | 'deprecated';
  summary?: string;
  description?: string;
  feature: string;
  params?: Field[];
  request?: Field;
  requestExample?: string;
  response?: Field;
  responseExample?: string;
  statusCode?: string;
  source: { file: string; url: string };
  pathInferred?: boolean;
  contractNotes?: string[];
  contractErrors?: string[];
  partial?: boolean;
};

export type Feature = {
  id: string;
  section: string;
  title: string;
  siteRoute: string | null;
  summary: string;
  endpointIds: string[];
};

export type Section = { id: string; title: string; blurb: string };

type Docs = {
  generatedAt: string;
  source: { repo: string; sha: string | null; contracts: number };
  sections: Section[];
  features: Feature[];
  endpoints: Endpoint[];
  filterGuide: string | null;
  problems: { file: string; errors: string[] }[];
};

export const docs = raw as unknown as Docs;

const byId = new Map(docs.endpoints.map((e) => [e.id, e]));
export const SITE = 'https://www.usaspending.gov';
export const API_HOST = 'https://api.usaspending.gov';

export function endpoint(id: string) {
  return byId.get(id);
}
export function feature(id: string) {
  return docs.features.find((f) => f.id === id);
}
export function featureEndpoints(f: Feature) {
  return f.endpointIds.map((id) => byId.get(id)!).filter(Boolean);
}
export function sectionFeatures(sectionId: string) {
  return docs.features.filter((f) => f.section === sectionId);
}
export function endpointHref(e: Endpoint) {
  return `/reference/${e.feature}/${e.id}`;
}
export function siteUrl(route: string | null) {
  if (!route) return null;
  // Routes with parameters point at the feature's landing page.
  const base = route.split('/:')[0];
  return `${SITE}${base}`;
}
export function contractNotes(e: Endpoint) {
  const notes = [...(e.contractNotes || [])];
  if (e.pathInferred) notes.push("The contract doesn't state its URL. This path comes from the contract's location in the repo, which mirrors the URL by convention, and matches how usaspending.gov calls it.");
  if (e.partial) notes.push('Only part of this contract could be read, so some fields may be missing here. The source contract has the rest.');
  return notes;
}

'use client';
import { useState } from 'react';

export function CodeBlock({ code, label, lang = 'json' }: { code: string; label?: string; lang?: string }) {
  const [copied, setCopied] = useState(false);
  async function copy() {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setCopied(false);
    }
  }
  return (
    <figure className="code">
      <figcaption className="code-bar">
        <span>{label || lang.toUpperCase()}</span>
        <button type="button" className="code-copy" onClick={copy}>
          {copied ? 'Copied' : 'Copy'}
        </button>
      </figcaption>
      <pre tabIndex={0}><code>{code}</code></pre>
    </figure>
  );
}

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeSlug from 'rehype-slug';

// Renders contract prose and hand-written content. Links to usaspending.gov and GitHub open normally;
// relative links were already rewritten by the generator.
export function Markdown({ children, className }: { children?: string; className?: string }) {
  if (!children) return null;
  return (
    <div className={className ? `prose ${className}` : 'prose'}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeSlug]}>
        {children}
      </ReactMarkdown>
    </div>
  );
}

export function MethodBadge({ method, size = 'md' }: { method: string; size?: 'sm' | 'md' }) {
  return <span className={`method method-${method.toLowerCase()} method-${size}`}>{method}</span>;
}

import Link from 'next/link';
import { docs, sectionFeatures, featureEndpoints, endpointHref } from '@/lib/docs';
import { MethodBadge } from './MethodBadge';

export function Sidebar({ activeFeature, activeEndpoint }: { activeFeature?: string; activeEndpoint?: string }) {
  return (
    <nav className="sidebar" aria-label="Reference">
      <Link href="/reference" className="sidebar-top">All endpoints</Link>
      {docs.sections.map((s) => (
        <div key={s.id} className="sidebar-section">
          <p className="sidebar-heading">{s.title}</p>
          <ul>
            {sectionFeatures(s.id).map((f) => {
              const open = f.id === activeFeature;
              return (
                <li key={f.id}>
                  <Link href={`/reference/${f.id}`} aria-current={open && !activeEndpoint ? 'page' : undefined} className={open ? 'is-open' : undefined}>
                    {f.title} <span className="count">{f.endpointIds.length}</span>
                  </Link>
                  {open ? (
                    <ul className="sidebar-endpoints">
                      {featureEndpoints(f).map((e) => (
                        <li key={e.id}>
                          <Link href={endpointHref(e)} aria-current={e.id === activeEndpoint ? 'page' : undefined}>
                            <MethodBadge method={e.method} size="sm" />
                            <span>{e.title}</span>
                          </Link>
                        </li>
                      ))}
                    </ul>
                  ) : null}
                </li>
              );
            })}
          </ul>
        </div>
      ))}
    </nav>
  );
}

export function TallyMark({ size = 32 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 56 56" aria-hidden="true" focusable="false" className="tally-mark">
      <rect width="56" height="56" rx="10" fill="var(--color-action)" />
      {[14, 22, 30, 38].map((x) => (
        <line key={x} x1={x} y1="14" x2={x} y2="42" stroke="var(--color-on-band)" strokeWidth="4" strokeLinecap="round" />
      ))}
      <line x1="8" y1="38" x2="46" y2="18" stroke="var(--color-highlight)" strokeWidth="4" strokeLinecap="round" />
    </svg>
  );
}

