import { NextRequest, NextResponse } from 'next/server';

// Forwards live-console requests to the USAspending API. Only /api/v2/ paths on
// api.usaspending.gov are allowed, so this can never be used to reach any other host.
export const dynamic = 'force-dynamic';
export const maxDuration = 30;

const UPSTREAM = 'https://api.usaspending.gov/api/';
const SEGMENT = /^[A-Za-z0-9_\-.~%]+$/;
const MAX_BODY = 100_000;
const MAX_RESPONSE = 5_000_000;

function target(req: NextRequest, segments: string[]) {
  if (segments[0] !== 'v2' || segments.some((s) => !SEGMENT.test(s) || s === '..' || s === '.')) return null;
  const trailing = req.nextUrl.pathname.endsWith('/') ? '/' : '';
  return `${UPSTREAM}${segments.join('/')}${trailing}${req.nextUrl.search}`;
}

async function forward(req: NextRequest, segments: string[], method: 'GET' | 'POST') {
  const url = target(req, segments);
  if (!url) return NextResponse.json({ error: 'The console only calls /api/v2/ endpoints on api.usaspending.gov.' }, { status: 400 });
  let body: string | undefined;
  if (method === 'POST') {
    body = await req.text();
    if (body.length > MAX_BODY) return NextResponse.json({ error: 'Request body is too large for the console (100 KB max).' }, { status: 413 });
  }
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 25_000);
  try {
    const started = Date.now();
    const res = await fetch(url, {
      method,
      body,
      headers: { 'content-type': 'application/json', accept: 'application/json', 'user-agent': 'Tally API docs live console (usaspending-api.vercel.app)' },
      signal: ctrl.signal,
      cache: 'no-store',
    });
    const buf = await res.arrayBuffer();
    const truncated = buf.byteLength > MAX_RESPONSE;
    const text = new TextDecoder().decode(truncated ? buf.slice(0, MAX_RESPONSE) : buf);
    const headers: Record<string, string> = {
      'content-type': res.headers.get('content-type') || 'application/json',
      'x-upstream-ms': String(Date.now() - started),
      'x-upstream-url': url,
    };
    if (truncated) headers['x-truncated'] = 'true';
    if (method === 'GET' && res.ok) headers['cache-control'] = 'public, s-maxage=3600, stale-while-revalidate=86400';
    return new NextResponse(text, { status: res.status, headers });
  } catch (err) {
    const aborted = err instanceof Error && err.name === 'AbortError';
    return NextResponse.json({ error: aborted ? 'The USAspending API took longer than 25 seconds to answer.' : 'Could not reach the USAspending API.' }, { status: 504 });
  } finally {
    clearTimeout(timer);
  }
}

export async function GET(req: NextRequest, { params }: { params: { path: string[] } }) {
  return forward(req, params.path, 'GET');
}
export async function POST(req: NextRequest, { params }: { params: { path: string[] } }) {
  return forward(req, params.path, 'POST');
}

import type { Field } from '@/lib/docs';
import { Markdown } from './Markdown';

function typeLabel(f: Field): string {
  if (f.type === 'array') return f.items ? `array of ${f.items.ref || typeLabel(f.items)}` : 'array';
  if (f.type === 'enum') return `enum${f.valueType ? ` (${f.valueType})` : ''}`;
  if (f.type === 'oneOf') return 'one of';
  return f.ref && !['object', 'array', 'enum'].includes(f.type) ? f.ref : f.ref ? `${f.type} · ${f.ref}` : f.type;
}

function childrenOf(f: Field): Field[] | undefined {
  if (f.fields?.length) return f.fields;
  if (f.type === 'array' && f.items?.fields?.length) return f.items.fields;
  return undefined;
}

function show(v: unknown) {
  return typeof v === 'string' ? v : JSON.stringify(v);
}

function Row({ f, depth }: { f: Field; depth: number }) {
  const kids = childrenOf(f);
  const enumVals = f.enum || (f.type === 'array' ? f.items?.enum : undefined);
  const refDesc = f.refDescription || (f.type === 'array' ? f.items?.refDescription : undefined);
  const body = (
    <>
      {f.description ? <Markdown className="field-desc">{f.description}</Markdown> : null}
      {!f.description && refDesc ? <Markdown className="field-desc">{refDesc}</Markdown> : null}
      {enumVals?.length ? (
        <div className="field-enum">
          <span className="field-meta-label">Allowed values</span>
          <ul>
            {enumVals.slice(0, 60).map((v, i) => (
              <li key={i}><code>{show(v.value)}</code>{v.description ? <span> {v.description}</span> : null}</li>
            ))}
            {enumVals.length > 60 ? <li>and {enumVals.length - 60} more in the source contract</li> : null}
          </ul>
        </div>
      ) : null}
      {f.default !== undefined ? <p className="field-meta"><span className="field-meta-label">Default</span> <code>{show(f.default)}</code></p> : null}
      {f.example !== undefined && f.type !== 'object' ? <p className="field-meta"><span className="field-meta-label">Example</span> <code>{show(f.example)}</code></p> : null}
      {f.options?.length ? (
        <div className="field-oneof">
          {f.options.map((o, i) => (
            <div key={i} className="field-option">
              <span className="field-meta-label">Option {i + 1}</span>
              <FieldList fields={o.fields} depth={depth + 1} />
            </div>
          ))}
        </div>
      ) : null}
    </>
  );
  const head = (
    <span className="field-head">
      <code className="field-name">{f.name}</code>
      <span className="field-type">{typeLabel(f)}</span>
      {f.required ? <span className="field-req">Required</span> : null}
      {f.nullable ? <span className="field-null">Nullable</span> : null}
    </span>
  );
  if (kids) {
    return (
      <li className="field">
        <details open={depth === 0 && kids.length <= 12}>
          <summary>{head}<span className="field-count">{kids.length} {kids.length === 1 ? 'field' : 'fields'}</span></summary>
          {body}
          <FieldList fields={kids} depth={depth + 1} />
        </details>
      </li>
    );
  }
  return (
    <li className="field">
      {head}
      {body}
    </li>
  );
}

export function FieldList({ fields, depth = 0 }: { fields: Field[]; depth?: number }) {
  if (!fields.length) return <p className="muted">No fields are documented for this object.</p>;
  return (
    <ul className={`fields depth-${Math.min(depth, 4)}`}>
      {fields.map((f, i) => <Row key={`${f.name}-${i}`} f={f} depth={depth} />)}
    </ul>
  );
}

export function Schema({ field }: { field?: Field }) {
  if (!field) return <p className="muted">The contract doesn&apos;t describe this body.</p>;
  const kids = childrenOf(field);
  if (kids) return <FieldList fields={kids} />;
  return <FieldList fields={[{ ...field, name: '(body)' }]} />;
}

'use client';
import { useMemo, useState } from 'react';

type Param = { name?: string; in?: 'path' | 'query'; required?: boolean; example?: unknown; default?: unknown; enum?: { value: unknown }[]; type: string };

const API = 'https://api.usaspending.gov';

function initial(p: Param) {
  const v = p.example ?? (p.in === 'path' ? '' : undefined);
  return v === undefined || v === null ? '' : typeof v === 'string' ? v : JSON.stringify(v);
}

export function Console({ method, path, params = [], requestExample }: { method: string; path: string; params?: Param[]; requestExample?: string }) {
  const [values, setValues] = useState<Record<string, string>>(() => Object.fromEntries(params.map((p) => [p.name || '', initial(p)])));
  const [body, setBody] = useState(requestExample || '{}');
  const [state, setState] = useState<{ status?: number; ms?: number; text?: string; error?: string; loading?: boolean; truncated?: boolean }>({});

  const built = useMemo(() => {
    let p = path;
    const q = new URLSearchParams();
    for (const prm of params) {
      const v = values[prm.name || '']?.trim();
      if (prm.in === 'path') p = p.replace(`{${prm.name}}`, v ? encodeURIComponent(v) : `{${prm.name}}`);
      else if (v) q.set(prm.name || '', v);
    }
    const qs = q.toString();
    return { path: p, url: `${p}${qs ? `?${qs}` : ''}`, missing: /\{[^}]+\}/.test(p) };
  }, [path, params, values]);

  let bodyError: string | null = null;
  if (method === 'POST') {
    try { JSON.parse(body); } catch { bodyError = 'The request body isn’t valid JSON yet.'; }
  }

  const curl = method === 'POST'
    ? `curl -X POST '${API}${built.url}' \\\n  -H 'Content-Type: application/json' \\\n  -d '${compact(body)}'`
    : `curl '${API}${built.url}'`;

  async function send() {
    setState({ loading: true });
    const started = performance.now();
    try {
      const res = await fetch(`/api/proxy${built.url.replace(/^\/api/, '')}`, {
        method,
        headers: { 'content-type': 'application/json' },
        body: method === 'POST' ? body : undefined,
      });
      const text = await res.text();
      let pretty = text;
      try { pretty = JSON.stringify(JSON.parse(text), null, 2); } catch { /* not JSON */ }
      const cap = 200_000;
      setState({ status: res.status, ms: Math.round(performance.now() - started), text: pretty.length > cap ? `${pretty.slice(0, cap)}\n…` : pretty, truncated: pretty.length > cap || res.headers.get('x-truncated') === 'true' });
    } catch {
      setState({ error: 'The request didn’t complete. Check your connection and try again.' });
    }
  }

  return (
    <section className="console" aria-labelledby="console-title">
      <div className="console-head">
        <h2 id="console-title">Try it</h2>
        <p>Runs against the live API. Responses are real data.</p>
      </div>
      <div className="console-url"><span className={`method method-${method.toLowerCase()} method-sm`}>{method}</span><code>{built.url}</code></div>
      {params.length ? (
        <div className="console-params">
          {params.map((p) => {
            const id = `param-${p.name}`;
            return (
              <div key={p.name} className="console-field">
                <label htmlFor={id}>
                  <code>{p.name}</code> <span className="muted">{p.in}{p.required ? ', required' : ''}</span>
                </label>
                {p.enum?.length ? (
                  <select id={id} value={values[p.name || ''] ?? ''} onChange={(e) => setValues({ ...values, [p.name || '']: e.target.value })}>
                    <option value="">{p.required ? 'Choose a value' : 'Not set'}</option>
                    {p.enum.map((o) => <option key={String(o.value)} value={String(o.value)}>{String(o.value)}</option>)}
                  </select>
                ) : (
                  <input id={id} type="text" value={values[p.name || ''] ?? ''} onChange={(e) => setValues({ ...values, [p.name || '']: e.target.value })} placeholder={p.default !== undefined ? `Default: ${String(p.default)}` : undefined} />
                )}
              </div>
            );
          })}
        </div>
      ) : null}
      {method === 'POST' ? (
        <div className="console-field">
          <label htmlFor="console-body">Request body</label>
          <textarea id="console-body" spellCheck={false} value={body} onChange={(e) => setBody(e.target.value)} rows={Math.min(18, Math.max(6, body.split('\n').length + 1))} aria-describedby={bodyError ? 'console-body-error' : undefined} />
          {bodyError ? <p id="console-body-error" className="console-error">{bodyError}</p> : null}
        </div>
      ) : null}
      <div className="console-actions">
        <button type="button" className="button" onClick={send} disabled={state.loading || !!bodyError || built.missing}>
          {state.loading ? 'Sending…' : 'Send request'}
        </button>
        {built.missing ? <span className="muted">Fill in the path parameters first.</span> : null}
      </div>
      <details className="console-curl">
        <summary>Copy as curl</summary>
        <pre tabIndex={0}><code>{curl}</code></pre>
      </details>
      <div aria-live="polite">
        {state.error ? <p className="console-error">{state.error}</p> : null}
        {state.status !== undefined ? (
          <div className="console-result">
            <p className="console-status">
              <span className={state.status < 400 ? 'ok' : 'bad'}>{state.status}</span> in {state.ms} ms
              {state.truncated ? <span className="muted"> · showing the first part of a large response</span> : null}
            </p>
            <pre tabIndex={0} className="console-response"><code>{state.text}</code></pre>
          </div>
        ) : null}
      </div>
    </section>
  );
}

function compact(s: string) {
  try { return JSON.stringify(JSON.parse(s)).replace(/'/g, "'\\''"); } catch { return s.replace(/'/g, "'\\''"); }
}

/* Tally global styles. Components read semantic tokens from tokens.css only. */
:root {
  /* Raw family names. The semantic --font-* tokens in tokens.css add fallbacks. */
