.with-sidebar { max-width: var(--size-page); margin: 0 auto; padding: 0 var(--space-5); display: grid; grid-template-columns: var(--size-sidebar) minmax(0, 1fr); gap: var(--space-7); }
.content { min-width: 0; padding-bottom: var(--space-7); }

