.card { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-5); border: 1px solid var(--color-rule); border-radius: var(--radius-md); text-decoration: none; color: var(--color-text-body); background: var(--color-bg); border-top: 4px solid var(--color-action); }
.card:hover { border-color: var(--color-action); color: var(--color-text-body); }
