.card-title { font-weight: 700; font-size: 19px; color: var(--color-text); line-height: 1.3; }
.card-body { font-size: 15px; }
.menus { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-5); margin-top: var(--space-5); }
.menu { border-top: 4px solid var(--color-band); padding-top: var(--space-4); }
.menu h3 { font-family: var(--font-display); font-weight: 800; text-transform: uppercase; font-size: 26px; }
