.field-head { display: inline-flex; align-items: baseline; gap: var(--space-2); flex-wrap: wrap; }
.field-name { font-weight: 500; color: var(--color-text); font-size: 15px; }
.field-type { font-family: var(--font-mono); font-size: 13px; color: var(--color-text-muted); }
.field-req { font-size: 12px; font-weight: 700; color: var(--color-danger); }
.field-null { font-size: 12px; color: var(--color-text-muted); }
.field-count { font-size: 13px; color: var(--color-text-muted); }
.field-desc { font-size: 15px; margin-top: var(--space-1); }
