.field-meta { font-size: 14px; margin: var(--space-1) 0 0; }
.field-meta-label { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--color-text-muted); margin-right: var(--space-1); }
