.field-option { margin-top: var(--space-2); }

/* Code */
.code { margin: var(--space-4) 0; border-radius: var(--radius-md); overflow: hidden; background: var(--color-code-bg); }
.code-bar { display: flex; justify-content: space-between; align-items: center; padding: var(--space-1) var(--space-1) var(--space-1) var(--space-4); font-size: 13px; color: var(--color-code-text); border-bottom: 1px solid rgba(255,255,255,0.12); }
