.console input, .console select, .console textarea { font: inherit; font-size: 15px; min-height: 44px; padding: var(--space-2) var(--space-3); border: 1px solid var(--color-text-muted); border-radius: var(--radius-sm); background: var(--color-bg); color: var(--color-text); width: 100%; }
.console textarea { font-family: var(--font-mono); font-size: 13.5px; line-height: 1.5; resize: vertical; }
.console-actions { display: flex; align-items: center; gap: var(--space-3); margin-top: var(--space-4); flex-wrap: wrap; }
.console-curl { margin-top: var(--space-3); font-size: 14px; }
