.console-curl pre { background: var(--color-code-bg); border-radius: var(--radius-sm); margin-top: var(--space-2); }
.console-error { color: var(--color-danger); font-weight: 600; }
.console-result { margin-top: var(--space-4); margin-bottom: var(--space-5); }
.console-status { font-weight: 600; color: var(--color-text); }
.console-status .ok { color: var(--color-method-get); }
.console-status .bad { color: var(--color-danger); }
.console-response { background: var(--color-code-bg); border-radius: var(--radius-sm); }
.console > :last-child { margin-bottom: var(--space-5); }

/* Prose (markdown) */
.prose { max-width: var(--size-content); }
